code_sketch:
for attempt := 1; ; attempt++ {
    resp, err := client.Do(req)
    if err == nil { return resp, nil }
    if !isTransient(err) || attempt >= maxAttempts { return nil, err }
    timer := time.NewTimer(backoff(attempt))       // capped, jittered
    select {
    case <-ctx.Done():
        timer.Stop()
        return nil, ctx.Err()
    case <-timer.C:
    }
}

